// ─── Public API ───────────────────────────────────────────────────────────────

let _lang = 'en';   // safe default before initI18n() detects the system language

function getCurrentLang() { return _lang; }

function t(key, vars) {
  // Fallback chain: current language → English → Italian → the raw key.
  const str = TRANSLATIONS[_lang]?.[key] ?? TRANSLATIONS['en']?.[key] ?? TRANSLATIONS['it']?.[key] ?? key;
  if (!vars) return str;
  return str.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? `{${k}}`);
}

function applyLanguage(lang) {
  if (!TRANSLATIONS[lang]) return;
  _lang = lang;
  try { localStorage.setItem('amelie-lang', lang); } catch(_) {}

  // Update all [data-i18n] text content
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.dataset.i18n;
    const val = t(key);
    if (val) el.textContent = val;
  });

  // Update [data-i18n-html] (strings that contain inline markup)
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const val = t(el.dataset.i18nHtml);
    if (val) el.innerHTML = val;
  });

  // Update [data-i18n-placeholder]
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const val = t(el.dataset.i18nPlaceholder);
    if (val) el.placeholder = val;
  });

  // Update [data-i18n-title]
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const val = t(el.dataset.i18nTitle);
    if (val) el.title = val;
  });

  // Highlight active language pill
  document.querySelectorAll('.lang-pill').forEach(pill => {
    pill.classList.toggle('active', pill.dataset.lang === lang);
  });
  // Update the language dropdown label (flag + name)
  const langCur = document.getElementById('lang-dd-current');
  const langAct = document.querySelector(`.lang-pill[data-lang="${lang}"]`);
  if (langCur && langAct) langCur.textContent = langAct.textContent.trim();

  // Dispatch event so app.js can react
  document.dispatchEvent(new CustomEvent('amelie:lang-changed', { detail: { lang } }));
}

function initI18n() {
  // Language selection order:
  //   1. the user's saved choice (if any);
  //   2. otherwise the SYSTEM language, if it's one of the supported locales;
  //   3. otherwise English (the universal fallback — not Italian).
  try {
    const saved = localStorage.getItem('amelie-lang');
    if (saved && TRANSLATIONS[saved]) {
      _lang = saved;
    } else {
      const sys = String(navigator.language || (navigator.languages && navigator.languages[0]) || 'en')
        .slice(0, 2).toLowerCase();
      _lang = TRANSLATIONS[sys] ? sys : 'en';
    }
  } catch(_) { _lang = 'en'; }

  // Wire lang pills
  document.querySelectorAll('.lang-pill').forEach(pill => {
    pill.addEventListener('click', () => applyLanguage(pill.dataset.lang));
  });

  // Apply on load
  applyLanguage(_lang);
}

// Export
window.i18n = { t, applyLanguage, getCurrentLang, initI18n };
